final class Signal {
    public function __construct(public readonly string $name, public readonly int $rate, public readonly array $samples, public readonly string $origin = 'input', public readonly array $ingredients = []) {}
}
function traceLines(Signal $signal, int $depth, array &$lines): void { $lines[] = str_repeat('  ', $depth) . "$signal->name <- $signal->origin"; foreach ($signal->ingredients as $ingredient) traceLines($ingredient, $depth + 1, $lines); }
